//! Byte-level checks for the restart caches (`write_all_data_to_disk`).
//!
//! The C++ reference caches live under `reference/` (generated by
//! `scripts/reference_run.sh`); the Rust caches are written by a release
//! binary run into `reference/candidate_default`. The overlap caches are
//! compared byte for byte; `ec.bin` is compared section by section because
//! the reference leaves two regions uninitialised (see the module docs of
//! `assembly::read_cache`): the padding bits of each read's final packed
//! byte and the `name_index` slots beyond the sentinel.
//!
//! The round-trip test at the bottom only needs the Rust side.

use std::path::{Path, PathBuf};

use rshifiasm::assembly::read_cache::{load_all_data_from_disk, write_all_data_to_disk};
use rshifiasm::command_line::options::AssemblyOptions;
use rshifiasm::correction::ec_driver::{CorrectionState, PafList};
use rshifiasm::overlap::paf::PafHit;
use rshifiasm::reads::read_store::ReadStore;

fn repository_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).to_path_buf()
}

fn reference_directory() -> PathBuf {
    std::env::var_os("RSHIFIASM_CACHE_REFERENCE_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| repository_root().join("reference"))
}

/// One parsed `ec.bin`.
struct EcDump {
    adapter_length: i32,
    index_size: u64,
    name_index_size: u64,
    total_reads: u64,
    total_bases: u64,
    total_name_length: u64,
    /// Per read: the packed bytes as stored, plus the read length.
    packed: Vec<(Vec<u8>, u64)>,
    read_lengths: Vec<u64>,
    names: Vec<u8>,
    name_index: Vec<u64>,
    trio_flags: Vec<u8>,
    homozygous_coverage: i32,
    heterozygous_coverage: i32,
}

fn parse_ec_bin(path: &Path) -> EcDump {
    let data = std::fs::read(path).unwrap_or_else(|error| panic!("missing {}: {}", path.display(), error));
    let mut cursor = 0usize;
    let mut read_i32 = |cursor: &mut usize| {
        let value = i32::from_le_bytes(data[*cursor..*cursor + 4].try_into().unwrap());
        *cursor += 4;
        value
    };
    let mut read_u64 = |cursor: &mut usize| {
        let value = u64::from_le_bytes(data[*cursor..*cursor + 8].try_into().unwrap());
        *cursor += 8;
        value
    };

    let adapter_length = read_i32(&mut cursor);
    let index_size = read_u64(&mut cursor);
    let name_index_size = read_u64(&mut cursor);
    let total_reads = read_u64(&mut cursor);
    let total_bases = read_u64(&mut cursor);
    let total_name_length = read_u64(&mut cursor);

    for _ in 0..total_reads {
        let count = read_u64(&mut cursor);
        cursor += 8 * count as usize;
    }

    let mut read_lengths = Vec::with_capacity(total_reads as usize);
    for _ in 0..total_reads {
        read_lengths.push(read_u64(&mut cursor));
    }

    let mut packed = Vec::with_capacity(total_reads as usize);
    for &length in &read_lengths {
        let stored = (length / 4 + 1) as usize;
        packed.push((data[cursor..cursor + stored].to_vec(), length));
        cursor += stored;
    }

    let names = data[cursor..cursor + total_name_length as usize].to_vec();
    cursor += total_name_length as usize;

    let mut name_index = Vec::with_capacity(name_index_size as usize);
    for _ in 0..name_index_size {
        name_index.push(read_u64(&mut cursor));
    }

    let trio_flags = data[cursor..cursor + total_reads as usize].to_vec();
    cursor += total_reads as usize;

    let homozygous_coverage = read_i32(&mut cursor);
    let heterozygous_coverage = read_i32(&mut cursor);
    assert_eq!(cursor, data.len(), "trailing bytes in {}", path.display());

    EcDump {
        adapter_length,
        index_size,
        name_index_size,
        total_reads,
        total_bases,
        total_name_length,
        packed,
        read_lengths,
        names,
        name_index,
        trio_flags,
        homozygous_coverage,
        heterozygous_coverage,
    }
}

/// The packed tail of a read: how many bytes carry bases and the mask of the
/// valid bits in the last one (most-significant-base-first packing).
fn packed_tail(length: u64) -> (usize, u8) {
    let full = (length / 4) as usize;
    let remainder = (length % 4) as u32;
    if remainder == 0 {
        (full, 0)
    } else {
        (full + 1, 0xffu8 << ((4 - remainder) * 2))
    }
}

fn assert_ec_bins_match(reference: &Path, candidate: &Path) {
    let reference = parse_ec_bin(reference);
    let candidate = parse_ec_bin(candidate);

    assert_eq!(reference.adapter_length, candidate.adapter_length, "adapterLen");
    assert_eq!(reference.index_size, candidate.index_size, "index_size");
    assert_eq!(
        reference.name_index_size, candidate.name_index_size,
        "name_index_size"
    );
    assert_eq!(reference.total_reads, candidate.total_reads, "total_reads");
    assert_eq!(reference.total_bases, candidate.total_bases, "total_reads_bases");
    assert_eq!(
        reference.total_name_length, candidate.total_name_length,
        "total_name_length"
    );
    assert_eq!(reference.read_lengths, candidate.read_lengths, "read_length");

    for (read, (reference_packed, candidate_packed)) in reference
        .packed
        .iter()
        .zip(&candidate.packed)
        .enumerate()
    {
        let (carry_bytes, mask) = packed_tail(reference_packed.1);
        assert_eq!(reference_packed.1, candidate_packed.1, "read {} length", read);
        assert_eq!(
            reference_packed.0.len(),
            candidate_packed.0.len(),
            "read {} packed size",
            read
        );
        for index in 0..carry_bytes {
            if index + 1 == carry_bytes && mask != 0 {
                assert_eq!(
                    reference_packed.0[index] & mask,
                    candidate_packed.0[index] & mask,
                    "read {} packed base byte {}",
                    read,
                    index
                );
            } else if index < carry_bytes {
                assert_eq!(
                    reference_packed.0[index], candidate_packed.0[index],
                    "read {} packed base byte {}",
                    read, index
                );
            }
        }
        // The reference's final padding byte is uninitialised memory.
    }

    assert_eq!(reference.names, candidate.names, "name buffer");
    // Only the live entries plus the sentinel are defined; the reference's
    // remaining slots are allocation residue.
    let live_entries = reference.total_reads as usize + 1;
    assert_eq!(
        &reference.name_index[..live_entries],
        &candidate.name_index[..live_entries],
        "name_index live entries"
    );
    assert_eq!(reference.trio_flags, candidate.trio_flags, "trio_flag");
    assert_eq!(
        reference.homozygous_coverage, candidate.homozygous_coverage,
        "hom_cov"
    );
    assert_eq!(
        reference.heterozygous_coverage, candidate.heterozygous_coverage,
        "het_cov"
    );
}

fn assert_files_identical(reference: &Path, candidate: &Path, label: &str) {
    let reference_data = std::fs::read(reference)
        .unwrap_or_else(|error| panic!("missing {}: {}", reference.display(), error));
    let candidate_data = std::fs::read(candidate)
        .unwrap_or_else(|error| panic!("missing {}: {}", candidate.display(), error));
    assert_eq!(reference_data, candidate_data, "{} differs", label);
}

/// The Rust overlap caches are byte-identical to the C++ ones, and the
/// `ec.bin` sections match outside the reference's uninitialised regions.
#[test]
fn the_restart_caches_match_the_reference() {
    let reference = reference_directory();
    let ec_reference = reference.join("reference.ec.bin");
    let ec_candidate = reference.join("candidate_default.ec.bin");
    if !ec_reference.exists() || !ec_candidate.exists() {
        eprintln!("skipping: the reference or candidate caches are missing");
        return;
    }

    assert_files_identical(
        &reference.join("reference.ovlp.source.bin"),
        &reference.join("candidate_default.ovlp.source.bin"),
        "ovlp.source.bin",
    );
    assert_files_identical(
        &reference.join("reference.ovlp.reverse.bin"),
        &reference.join("candidate_default.ovlp.reverse.bin"),
        "ovlp.reverse.bin",
    );
    assert_ec_bins_match(&ec_reference, &ec_candidate);
}

fn sample_store() -> ReadStore {
    let mut store = ReadStore::default();
    store.push_read("read/one", b"ACGTACGTAC");
    store.push_read("read/two", b"TTTTGGGGCCCCAAAAN");
    store.trio_labels = vec![0, 1];
    store
}

fn sample_state(total_reads: usize) -> CorrectionState {
    let hit = PafHit {
        query_identifier: 0,
        query_start: 3,
        query_end: 10,
        target_identifier: 1,
        target_start: 2,
        target_end: 17,
        matching_length: 1,
        block_length: 15,
        reverse: true,
        without_large_indel: true,
        exact_region: false,
        exact_region_byte: 0,
        deleted: false,
    };
    let mut forward = vec![PafList::default(); total_reads];
    forward[0].hits.push(hit);
    let reverse = vec![PafList::default(); total_reads];
    CorrectionState { forward, reverse }
}

/// Writing a store and state and loading them back reproduces every field,
/// including the peaks written into the options.
#[test]
fn the_cache_round_trips_through_the_disk_format() {
    let scratch = std::env::temp_dir().join("rshifiasm_cache_round_trip");
    std::fs::create_dir_all(&scratch).expect("the scratch directory must be creatable");
    let mut options = AssemblyOptions::default();
    options.output_file_name = scratch.join("round").to_str().unwrap().to_string();
    options.homozygous_coverage = 36;
    options.heterozygous_coverage = 18;

    let reads = sample_store();
    let state = sample_state(reads.total_reads as usize);
    write_all_data_to_disk(&options, &reads, &state.forward, &state.reverse)
        .expect("the caches must be writable");

    let mut reopened = AssemblyOptions::default();
    reopened.output_file_name = options.output_file_name.clone();
    reopened.adapter_length = options.adapter_length;
    let (loaded_reads, loaded_state) =
        load_all_data_from_disk(&mut reopened).expect("the caches must be loadable");

    assert_eq!(loaded_reads.total_reads, reads.total_reads);
    assert_eq!(loaded_reads.total_bases, reads.total_bases);
    assert_eq!(loaded_reads.read_names, reads.read_names);
    assert_eq!(loaded_reads.read_lengths, reads.read_lengths);
    assert_eq!(loaded_reads.trio_labels, reads.trio_labels);
    for (loaded, original) in loaded_reads.sequences.iter().zip(&reads.sequences) {
        assert_eq!(loaded.length, original.length);
        assert_eq!(loaded.ambiguous_positions, original.ambiguous_positions);
        assert_eq!(
            loaded.packed_bases, original.packed_bases,
            "packed bases of a {}-base read",
            original.length
        );
    }
    assert_eq!(reopened.homozygous_coverage, 36);
    assert_eq!(reopened.heterozygous_coverage, 18);

    assert_eq!(loaded_state.forward.len(), state.forward.len());
    assert_eq!(loaded_state.forward[0].hits, state.forward[0].hits);
    assert_eq!(
        loaded_state.forward[0].is_fully_corrected,
        state.forward[0].is_fully_corrected
    );
    assert_eq!(loaded_state.reverse.len(), state.reverse.len());

    std::fs::remove_dir_all(&scratch).ok();
}
